DROP TRIGGER releases_timeline ON releases;DROP TRIGGER deployments_timeline ON deployments;DROP TRIGGER migration_deployments_timeline ON migration_deployments;DROP TRIGGER security_scans_timeline ON security_release_scans;
CREATE OR REPLACE FUNCTION platform_audiences() RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT coalesce(jsonb_agg(id::text),'[]'::jsonb) FROM organizations WHERE organization_type='platform' AND status='active'$$;
CREATE OR REPLACE FUNCTION emit_platform_operational_event(event_name text,category_name text,aggregate_name text,aggregate_uuid uuid,event_status text,summary_text text) RETURNS void LANGUAGE plpgsql AS $$BEGIN INSERT INTO outbox_events(id,event_type,aggregate_type,aggregate_id,payload,metadata,occurred_at) VALUES(gen_random_uuid(),event_name,aggregate_name,aggregate_uuid,jsonb_build_object('status',event_status),jsonb_build_object('schemaVersion',1,'timeline',jsonb_build_object('organizationIds',platform_audiences(),'category',category_name,'source','release_automation','sourceSystem','deployment_pipeline','summary',summary_text,'status',event_status)),now());END$$;
CREATE OR REPLACE FUNCTION release_event() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE event_name text;BEGIN event_name:=CASE NEW.status WHEN 'created' THEN 'release.created' WHEN 'validated' THEN 'release.staging_validation_passed' WHEN 'approved' THEN 'release.approved' WHEN 'failed' THEN 'release.build_failed' WHEN 'rolling_back' THEN 'release.rollback_started' WHEN 'rolled_back' THEN 'release.rollback_completed' WHEN 'cancelled' THEN 'release.cancelled' ELSE 'release.'||NEW.status END;PERFORM emit_platform_operational_event(event_name,'release','release',NEW.id,NEW.status,initcap(replace(event_name,'.',' ')));RETURN NEW;END$$;
CREATE OR REPLACE FUNCTION deployment_event() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE event_name text;BEGIN event_name:=CASE WHEN NEW.environment='staging' AND NEW.status='completed' THEN 'release.staging_deployed' WHEN NEW.environment='production' AND NEW.status='started' THEN 'release.production_deployment_started' WHEN NEW.environment='production' AND NEW.status='completed' THEN 'release.production_deployment_completed' WHEN NEW.environment='production' AND NEW.status='failed' THEN 'release.production_deployment_failed' WHEN NEW.status='rollback_started' THEN 'release.rollback_started' WHEN NEW.status='rolled_back' THEN 'release.rollback_completed' ELSE 'deployment.'||NEW.environment||'.'||NEW.status END;PERFORM emit_platform_operational_event(event_name,'deployment','deployment',NEW.id,NEW.status,initcap(replace(event_name,'.',' ')));RETURN NEW;END$$;
CREATE OR REPLACE FUNCTION migration_event() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE event_name text;BEGIN event_name:=CASE NEW.status WHEN 'started' THEN 'database.migration_started' WHEN 'completed' THEN 'database.migration_completed' WHEN 'failed' THEN 'database.migration_failed' ELSE 'database.migration_'||NEW.status END;PERFORM emit_platform_operational_event(event_name,'migration','database_migration',NEW.id,NEW.status,initcap(replace(event_name,'.',' ')));RETURN NEW;END$$;
CREATE OR REPLACE FUNCTION security_scan_event() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE event_name text;BEGIN event_name:=CASE NEW.status WHEN 'passed' THEN 'security.release_scan_passed' WHEN 'failed' THEN 'security.release_scan_failed' WHEN 'exception_approved' THEN 'security.exception_approved' ELSE 'security.release_scan_started' END;PERFORM emit_platform_operational_event(event_name,'security','security_release_scan',NEW.id,NEW.status,initcap(replace(event_name,'.',' ')));RETURN NEW;END$$;
CREATE TRIGGER releases_timeline AFTER INSERT OR UPDATE OF status ON releases FOR EACH ROW EXECUTE FUNCTION release_event();CREATE TRIGGER deployments_timeline AFTER INSERT OR UPDATE OF status ON deployments FOR EACH ROW EXECUTE FUNCTION deployment_event();CREATE TRIGGER migration_deployments_timeline AFTER INSERT OR UPDATE OF status ON migration_deployments FOR EACH ROW EXECUTE FUNCTION migration_event();CREATE TRIGGER security_scans_timeline AFTER INSERT OR UPDATE OF status ON security_release_scans FOR EACH ROW EXECUTE FUNCTION security_scan_event();
